import {parts} from './data.js';
import {$,intro,icon,read,save,esc} from './ui.js';
let current='resistor',tab='overview',view='package',filter='',query='';
let visited=read('visited',['resistor']);if(!Array.isArray(visited))visited=['resistor'];
export function atlas(id){
 if(parts.some(p=>p.id===id))current=id;
 $('#main').innerHTML=intro('01 / the component atlas','Small parts.<br><em>Big possibilities.</em>','Every board has a story. Start by clicking a component, then change a circuit to see what it actually does.')+`
 <section class="explorer-grid" aria-label="Interactive component atlas"><div class="board-side"><div class="panel-top"><span class="section-label">Meet your circuit board</span><div class="segmented" aria-label="Board display"><button data-view="package" class="${view==='package'?'active':''}" aria-pressed="${view==='package'}">Components</button><button data-view="symbol" class="${view==='symbol'?'active':''}" aria-pressed="${view==='symbol'}">Symbols</button></div></div>
 <div class="board"><svg class="traces" viewBox="0 0 800 500" preserveAspectRatio="none" aria-hidden="true"><defs><pattern id="dots" width="20" height="20" patternUnits="userSpaceOnUse"><circle cx="10" cy="10" r=".6" fill="#678b62"/></pattern></defs><rect width="800" height="500" fill="url(#dots)"/><g fill="none" stroke="#517550" stroke-width="2"><path d="M60 220h80v-100h200v100h160V115h140M60 240h110v130h125v-95h215v130h170M180 120v90h120v40h300v-90h140M355 105v60h-80v140h-55v120M660 220h-75v65h-85M510 410v40H325V320H95M655 355h-75v-65h-80M650 420h80V285h-90M200 440h-60v-50h-40M365 370h80v65M75 260h40v-70h75M485 100h55v60h110M295 200V90h140"/><path d="M70 160h45V65h550v45M720 145h30v315H80V290" stroke="#73915c" stroke-width="4"/></g><g fill="#b5aa6a">${[[140,120],[500,220],[600,160],[170,240],[325,320],[445,435],[275,165],[640,285],[115,190],[295,90],[540,160]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="4"/><circle cx="${x}" cy="${y}" r="1.5" fill="#294936"/>`).join('')}</g></svg><i class="hole"></i><i class="hole"></i><i class="hole"></i><i class="hole"></i><span class="board-name">CIRCUIT WORKSHOP / REV 01</span><span class="board-word">A MAP OF POSSIBILITIES</span>${parts.map(p=>`<button class="pcb-part ${p.id===current?'selected':''}" data-part="${p.id}" style="left:${p.pos[0]}%;top:${p.pos[1]}%" aria-label="Explore ${p.name}" aria-pressed="${p.id===current}">${icon(p.id,view==='symbol')}<small>${p.ref}</small></button>`).join('')}</div>
 <div class="board-legend"><span><i></i>Select a part · illustrative layout</span><span>Traces are decorative</span></div></div><aside class="detail" id="part-detail" aria-label="Selected component"></aside></section>
 <section class="library"><div class="library-head"><h3>Your component collection <span id="explored"></span></h3><div class="library-controls"><input class="search" id="component-search" placeholder="Search name, marking…" aria-label="Search components" value="${esc(query)}"><select class="filter" id="component-filter" aria-label="Filter component category"><option value="">All families</option>${['Passive','Semiconductor','IC','Connection','Protection','Transducer'].map(v=>`<option ${filter===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="component-grid" id="component-grid"></div></section>
 <div class="bottom-callout"><span class="number">↗</span><p><strong>Recognising a part is just the beginning.</strong><br>Try a circuit. Make a prediction. Move a slider. See what changes.</p><a href="#lab/led">Go to circuit lab →</a></div>`;
 select(current);renderCards();
 $('#main').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.part)select(b.dataset.part);if(b.dataset.view){view=b.dataset.view;atlas()}if(b.dataset.detailTab){tab=b.dataset.detailTab;detail()}};
 $('#component-search').oninput=e=>{query=e.target.value;renderCards()};$('#component-filter').onchange=e=>{filter=e.target.value;renderCards()};
}
function select(id){current=id;tab='overview';if(!visited.includes(id)){visited.push(id);save('visited',visited)}document.querySelectorAll('[data-part]').forEach(b=>{b.classList.toggle(b.classList.contains('pcb-part')?'selected':'active',b.dataset.part===id);b.setAttribute('aria-pressed',String(b.dataset.part===id))});detail();renderCards()}
function detail(){const p=parts.find(x=>x.id===current);$('#part-detail').innerHTML=`<div class="eyebrow">${p.ref} / ${p.group} / ${p.unit}</div><div class="detail-title"><h2>${p.name}</h2>${icon(p.id)}</div><p class="tagline">${p.tag}</p><div class="detail-tabs" aria-label="Component information">${[['overview','Overview'],['types','Types'],['bench','On the bench']].map(([id,n])=>`<button class="${tab===id?'active':''}" data-detail-tab="${id}" aria-pressed="${tab===id}">${n}</button>`).join('')}</div><div class="detail-body">${tab==='overview'?`<p>${p.what}</p><h4>How it works</h4><p>${p.how}</p><h4>Where you’ll find it</h4><p class="use">${p.use}</p>`:tab==='types'?`<label class="small-note" for="part-type">Choose a type to compare</label><select id="part-type">${p.types.map(([n],i)=>`<option value="${i}">${n}</option>`).join('')}</select><p id="type-description">${p.types[0][1]}</p><h4>How to recognise it</h4><p>${p.identify}</p>`:`<h4>Measure & diagnose</h4><p>${p.test}</p><h4>At the soldering iron</h4><p>${p.solder}</p><h4>Keep in mind</h4><p>${p.care}</p>`}</div><a class="btn" href="#lab/${p.lab}">Explore a related circuit <span>↗</span></a>`;if($('#part-type'))$('#part-type').onchange=e=>$('#type-description').textContent=p.types[+e.target.value][1]}
function renderCards(){const filtered=parts.filter(p=>(!filter||p.group===filter)&&(`${p.name} ${p.ref} ${p.tag} ${p.types.flat().join(' ')}`.toLowerCase().includes(query.toLowerCase())));$('#component-grid').innerHTML=filtered.map(p=>`<button class="component-card ${p.id===current?'active':''} ${visited.includes(p.id)?'visited':''}" data-part="${p.id}" aria-pressed="${p.id===current}">${icon(p.id)}<span>${p.name}<small>${p.ref} · ${p.group}</small></span></button>`).join('')||'<p class="empty">No matching parts. Try another name or select all families.</p>';$('#explored').textContent=`${visited.length} / ${parts.length} explored`}
